556	+/**
557	+ * @brief 回连对账：记录（持久）↔ 槽位目标（本次开机）。
558	+ *
559	+ * @details
560	+ * 回连**只**该由 `autorc` 记录驱动：武装在 `companion_sensor_autorc_all()`
561	+ * → `ble_sensor_connect_addr()`，扫描回调本身不再替槽位挑设备（见
562	+ * `docs/ble/ble_sensor.md` §3.9.1）。于是两个方向相反的问题在同一条判据上：
563	+ *
564	+ *   - **记录有 ★、槽位地址空** → 武装没上（BLE 没 started、或记录是在 BLE
565	+ *     起来之后才写的），开机不会回连。
566	+ *   - **记录没有、槽位却有地址** → 有东西绕过记录在连，也就是"删了也回来"
567	+ *     的形态。修完之后不该出现。
568	+ *
569	+ * 两个地址都打全，方便和 `sys rec` / `sys found` 逐字节对（RPA 轮换的设备
570	+ * 会对不上，见 §3.7）。
571	+ */
572	+void myvendor_devctl_sensor_link_dump(void)
573	+{
574	+  myvendor_devctl_sensor_rec_t recs[MYVENDOR_DEVCTL_SENSOR_REC_MAX];
575	+  myvendor_sys_sensor_ui_t ui;
576	+  size_t n = 0;
577	+  uint8_t k;
578	+
579	+  myvendor_sys_sensor_ui_get(&ui);
580	+  (void)myvendor_devctl_sensor_recs_get(recs, MYVENDOR_DEVCTL_SENSOR_REC_MAX,
581	+                                        &n);
582	+
583	+  for (k = 0; k < MYVENDOR_DEVCTL_SENSOR_KIND_N; k++)
584	+    {
585	+      const myvendor_devctl_sensor_rec_t *rec = NULL;
586	+      const myvendor_sys_sensor_slot_t   *slot = NULL;
587	+      char ra[24];
588	+      char sa[24];
589	+      size_t r;
590	+      bool slot_have;
591	+
592	+      for (r = 0; r < n; r++)
593	+        {
594	+          if (recs[r].kind == k && recs[r].autorc)
595	+            {
596	+              rec = &recs[r];
597	+              break;
598	+            }
599	+        }
600	+
601	+      if (k < MYVENDOR_SYS_SENSOR_KIND_N)
602	+        {
603	+          slot = &ui.slot[k];
604	+          slot_have = (slot->addr[0] | slot->addr[1] | slot->addr[2] |
605	+                       slot->addr[3] | slot->addr[4] | slot->addr[5]) != 0;
606	+        }
607	+      else
608	+        {
609	+          slot_have = false;
610	+        }
611	+
612	+      if (rec == NULL && !slot_have)
613	+        {
614	+          continue;   /* 干净：既没配对目标，也没在连 */
615	+        }
616	+
617	+      if (rec != NULL)
618	+        {
619	+          srec_mac_fmt(rec->addr, ra, sizeof(ra));
620	+        }
621	+      else
622	+        {
623	+          snprintf(ra, sizeof(ra), "--");
624	+        }
625	+
626	+      if (slot_have)
627	+        {
628	+          srec_mac_fmt(slot->addr, sa, sizeof(sa));
629	+        }
630	+      else
631	+        {
632	+          snprintf(sa, sizeof(sa), "--");
633	+        }
634	+
635	+      printf("sys link %s  rec %s %s  slot %s %s\n", srec_kind_name(k),
636	+             rec != NULL ? "*" : "-", ra,
637	+             slot == NULL ? "--" :
638	+             slot->link == MYVENDOR_SYS_SENSOR_LINK_READY ? "ready" :
639	+             slot->link == MYVENDOR_SYS_SENSOR_LINK_CONNECTING ? "conn" : "idle",
640	+             sa);
641	+
642	+      if (rec != NULL && !slot_have)
643	+        {
644	+          printf("sys link %s  WARN 有回连记录但槽位没武装,开机不会回连\n",
645	+                 srec_kind_name(k));
646	+        }
647	+      else if (rec == NULL && slot_have)
648	+        {
649	+          printf("sys link %s  WARN 无回连记录却在连,有东西绕过 autorc\n",
650	+                 srec_kind_name(k));
651	+        }
652	+    }
653	+}
