896:  static const char * const names[] =
897:  {
898:    "EMERG", "ALERT", "CRIT", "ERROR", "WARN", "NOTICE", "INFO", "DEBUG"
899:  };
900:
901:  uint8_t mask;
902:  uint8_t old;
903:  int want = -1;
904:  int ret;
905:  int i;
906:
907:  if (argc < 2)
908:    {
909:      mask = myvendor_devctl_log_mask_get();
910:      printf("syslog mask 0x%02x  (%s)\n", (unsigned)mask,
911:             MYVENDOR_DEVCTL_LOG_KEY);
912:      for (i = 0; i < 8; i++)
913:        {
914:          printf("  %-6s %s\n", names[i],
915:                 (mask & LOG_MASK(i)) != 0 ? "on" : "off");
916:        }
917:
918:      return 0;
919:    }
920:
921:  if (strcmp(argv[1], "-h") == 0 || strcmp(argv[1], "help") == 0)
922:    {
923:      printf("ctl log                 print current syslog mask\n");
924:      printf("ctl log err|warn|notice|info|all   keep levels up to this\n");
925:      printf("ctl log silent          only EMERG\n");
926:      printf("ctl log 0x1f            set raw mask\n");
927:      printf("  saved as %s, restored on boot\n", MYVENDOR_DEVCTL_LOG_KEY);
928:      printf("  (printf is NOT syslog; NSH/apps keep printing)\n");
929:      return 0;
930:    }
931:
932:  if (strcmp(argv[1], "err") == 0 || strcmp(argv[1], "error") == 0)
933:    {
934:      want = LOG_UPTO(LOG_ERR);
935:    }
936:  else if (strcmp(argv[1], "warn") == 0 || strcmp(argv[1], "warning") == 0)
937:    {
938:      want = LOG_UPTO(LOG_WARNING);
939:    }
940:  else if (strcmp(argv[1], "notice") == 0)
941:    {
942:      want = LOG_UPTO(LOG_NOTICE);
943:    }
944:  else if (strcmp(argv[1], "info") == 0)
