1135:  uint32_t n;
1136:
1137:  if (argc >= 3 && strcmp(argv[1], "read") == 0)
1138:    {
1139:      off = strtoull(argv[2], NULL, 16);
1140:      n = (argc >= 4) ? (uint32_t)strtoul(argv[3], NULL, 10) : 1u;
1141:      if (n == 0u || n > 256u)
1142:        {
1143:          n = 1u;
1144:        }
1145:
1146:      return sf32lb_sd_raw_read(off, n);
1147:    }
1148:
1149:  if (argc >= 3 && strcmp(argv[1], "write") == 0)
1150:    {
1151:      off = strtoull(argv[2], NULL, 16);
1152:      n = (argc >= 4) ? (uint32_t)strtoul(argv[3], NULL, 10) : 1u;
1153:      if (n == 0u || n > 256u)
1154:        {
1155:          n = 1u;
1156:        }
1157:
1158:      /* 写目标只有驱动器尾部那 1 MiB 是安全的（唯一不属于任何文件系统的
1159:       * 区域）；驱动内部还有一道不可绕过的闸门，这里只是提前给用法。 */
1160:      return sf32lb_sd_raw_write(off, n);
1161:    }
1162:
1163:  printf("ctl sd read  <hex_off> [n]    raw 512B block read, per-block timing\n");
1164:  printf("ctl sd write <hex_off> [n]    0xFF program + readback verify\n");
1165:  printf("  both bypass the dead gate on purpose, so they work on a dead card\n");
1166:  printf("  e.g. ctl sd read  200c2000 8        (LFS block 194)\n");
1167:  printf("       ctl sd write <card_size-4096> 32   (sacrificial tail ONLY)\n");
1168:  return -EINVAL;
1169:}
