377	int xfer_resolve(const char *in, size_t inlen, char *out, size_t outsz)
378	{
379	  const char *rest;
380	  size_t      restlen;
381	  const char *p;
382	  size_t      n;
383	
384	  if (in == NULL || inlen == 0 ||
385	      (inlen == 1 && (in[0] == '/' || in[0] == '.')))
386	    {
387	      return resolve_under(XFER_STORAGE_ROOT, NULL, 0, out, outsz);
388	    }
389	
390	  if (ota_request(in, inlen, &rest, &restlen))
391	    {
392	      return resolve_under(XFER_OTA_ROOT, rest, restlen, out, outsz);
393	    }
394	
395	  if (coredump_request(in, inlen, &rest, &restlen))
396	    {
397	      return resolve_under(XFER_COREDUMP_ROOT, rest, restlen, out, outsz);
398	    }
399	
400	  if (diag_request(in, inlen, &rest, &restlen))
401	    {
402	      return resolve_under(XFER_DIAG_ROOT, rest, restlen, out, outsz);
403	    }
404	
405	  if (fav_request(in, inlen))
406	    {
407	      size_t n = sizeof(XFER_FAV_PATH) - 1;
408	
409	      if (outsz <= n)
410	        {
411	          return ENAMETOOLONG;
412	        }
413	
414	      memcpy(out, XFER_FAV_PATH, n + 1);
415	      return 0;
416	    }
417	
418	  p = in;
419	  n = inlen;
420	  if (p[0] == '/')
421	    {
422	      if (!skip_abs_root(p, n, XFER_STORAGE_ROOT, &rest, &restlen))
423	        {
424	          return EACCES;
425	        }
426	
427	      p = rest;
428	      n = restlen;
429	    }
430	
431	  return resolve_under(XFER_STORAGE_ROOT, p, n, out, outsz);
432	}
