768	/** @brief 打开 *.part 写会话（可 resume）。 */
769	int xfer_write_open(const char *final_path, char *tmp_path, size_t tmp_sz,
770	                    int *fd, bool resume, uint32_t *out_off, uint32_t *out_crc)
771	{
772	  uint32_t crc  = 0;
773	  uint32_t size = 0;
774	  int      ret;
775	  int      flags;
776	
777	  if (final_path == NULL || tmp_path == NULL || fd == NULL)
778	    {
779	      return EINVAL;
780	    }
781	
782	  ensure_ota_dir(final_path);
783	
784	  ret = make_part_path(final_path, tmp_path, tmp_sz);
785	  if (ret != 0)
786	    {
787	      return ret;
788	    }
789	
790	  if (resume)
791	    {
792	      ret = hash_existing(tmp_path, &crc, &size);
793	      if (ret != 0)
794	        {
795	          return ret;
796	        }
797	    }
798	
799	  flags = O_WRONLY | O_CREAT;
800	  if (!resume)
801	    {
802	      flags |= O_TRUNC;
803	      crc   = 0;
804	      size  = 0;
805	    }
806	
807	  *fd = open(tmp_path, flags, 0666);
808	  if (*fd < 0)
809	    {
810	      return errno != 0 ? errno : EIO;
811	    }
812	
813	  if (resume && size > 0 && lseek(*fd, 0, SEEK_END) == (off_t)-1)
814	    {
815	      int e = errno != 0 ? errno : EIO;
816	      close(*fd);
817	      *fd = -1;
818	      return e;
819	    }
820	
821	  if (out_off != NULL)
822	    {
823	      *out_off = size;
824	    }
825	
826	  if (out_crc != NULL)
827	    {
828	      *out_crc = crc;
829	    }
830	
831	  return 0;
832	}
