834	/** @brief 向 *.part 追加数据。 */
835	int xfer_write_data(int fd, const uint8_t *buf, size_t len)
836	{
837	  if (fd < 0 || buf == NULL)
838	    {
839	      return EINVAL;
840	    }
841	
842	  while (len > 0)
843	    {
844	      size_t  chunk = len;
845	      ssize_t n;
846	
847	      if (chunk > XFER_WRITE_SLICE)
848	        {
849	          chunk = XFER_WRITE_SLICE;
850	        }
851	
852	      myvendor_watchdog_work_beat();
853	      myvendor_watchdog_hw_pet();
854	      n = write(fd, buf, chunk);
855	      if (n < 0)
856	        {
857	          return errno != 0 ? errno : EIO;
858	        }
859	
860	      if (n == 0)
861	        {
862	          return ENOSPC;
863	        }
864	
865	      buf += (size_t)n;
866	      len -= (size_t)n;
867	      myvendor_watchdog_work_beat();
868	      myvendor_watchdog_hw_pet();
869	      if (len > 0)
870	        {
871	          /* 让出 LFS 互斥，bicycle_ui 才能跑 lv_timer_handler。 */
872	          usleep(XFER_WRITE_YIELD_US);
873	        }
874	    }
875	
876	  return 0;
877	}
