}

/** @brief 自行车/vmap 是否必须推迟 LittleFS I/O。 */
bool myvendor_mtp_lfs_quiesce(void)
{
  bool q;

  pthread_mutex_lock(&g_mtp_lock);
  q = g_transfer_active || g_lfs_hold > 0
      || g_plug >= MYVENDOR_MTP_PLUG_ENUM || g_session;
  pthread_mutex_unlock(&g_mtp_lock);
  return q;
}

void myvendor_mtp_lfs_quiesce_why(char *buf, size_t n)
{
  bool     xfer;
  bool     sess;
  int      hold;
  unsigned plug;

  if (buf == NULL || n == 0u)
    {
      return;
    }

  pthread_mutex_lock(&g_mtp_lock);
  xfer = g_transfer_active;
  hold = g_lfs_hold;
  sess = g_session;
  plug = (unsigned)g_plug;
  pthread_mutex_unlock(&g_mtp_lock);

  /* plug 的语义见 myvendor_mtp_plug_t：0=OFF（未插/仅充电）, 1=ENUM, 2=ACTIVE。
   * 注意 quiesce 用的是 >= ENUM —— 只要主机选了 MTP 配置就算 busy，哪怕一次
   * 传输都没发生。仅充电若不自枚举应停在 0，所以这一项为 1/2 才是可疑点。 */
  snprintf(buf, n, "xfer=%d hold=%d sess=%d plug=%u",
           xfer ? 1 : 0, hold, sess ? 1 : 0, plug);
}

